// Package calc evaluates signed 64-bit integer expressions.
//
// Grammar:
//
//	expr    := term    (('+' | '-') term)*
//	term    := unary   (('*' | '/' | '%') unary)*
//	unary   := '-' unary | primary
//	primary := NUMBER | '(' expr ')'
//
// Any syntax error, division by zero, or overflow makes the whole expression invalid.
package calc

import (
	"errors"
	"math"
)

var (
	// ErrSyntax reports a malformed expression.
	ErrSyntax = errors.New("syntax error")
	// ErrDivByZero reports a division or remainder by zero.
	ErrDivByZero = errors.New("division by zero")
	// ErrOverflow reports a result outside the signed 64-bit range.
	ErrOverflow = errors.New("integer overflow")
)

// Evaluate returns the value of expr, or an error if it is malformed or not representable.
func Evaluate(expr []byte) (int64, error) {
	p := parser{src: expr}
	v, err := p.expr()
	if err != nil {
		return 0, err
	}
	if p.peek() != eof {
		return 0, ErrSyntax
	}
	return v, nil
}

// IsBlank reports whether line holds only spaces and tabs.
func IsBlank(line []byte) bool {
	for _, b := range line {
		if !isSpace(b) {
			return false
		}
	}
	return true
}

func isSpace(b byte) bool { return b == ' ' || b == '\t' }

func isDigit(b byte) bool { return b >= '0' && b <= '9' }

const eof = -1

type parser struct {
	src []byte
	pos int
}

// peek skips whitespace and returns the next byte without consuming it, or eof.
func (p *parser) peek() int {
	for p.pos < len(p.src) && isSpace(p.src[p.pos]) {
		p.pos++
	}
	if p.pos < len(p.src) {
		return int(p.src[p.pos])
	}
	return eof
}

func (p *parser) expr() (int64, error) {
	acc, err := p.term()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '+' && op != '-' {
			return acc, nil
		}
		p.pos++
		rhs, err := p.term()
		if err != nil {
			return 0, err
		}
		if op == '+' {
			acc, err = add(acc, rhs)
		} else {
			acc, err = sub(acc, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

func (p *parser) term() (int64, error) {
	acc, err := p.unary()
	if err != nil {
		return 0, err
	}
	for {
		op := p.peek()
		if op != '*' && op != '/' && op != '%' {
			return acc, nil
		}
		p.pos++
		rhs, err := p.unary()
		if err != nil {
			return 0, err
		}
		switch op {
		case '*':
			acc, err = mul(acc, rhs)
		case '/':
			acc, err = div(acc, rhs)
		case '%':
			acc, err = rem(acc, rhs)
		}
		if err != nil {
			return 0, err
		}
	}
}

func (p *parser) unary() (int64, error) {
	if p.peek() != '-' {
		return p.primary()
	}
	p.pos++
	v, err := p.unary()
	if err != nil {
		return 0, err
	}
	if v == math.MinInt64 {
		return 0, ErrOverflow
	}
	return -v, nil
}

func (p *parser) primary() (int64, error) {
	c := p.peek()
	switch {
	case c == '(':
		p.pos++
		v, err := p.expr()
		if err != nil {
			return 0, err
		}
		if p.peek() != ')' {
			return 0, ErrSyntax
		}
		p.pos++
		return v, nil
	case c >= '0' && c <= '9':
		return p.number()
	default:
		return 0, ErrSyntax
	}
}

func (p *parser) number() (int64, error) {
	var v int64
	for p.pos < len(p.src) && isDigit(p.src[p.pos]) {
		d := int64(p.src[p.pos] - '0')
		if v > (math.MaxInt64-d)/10 {
			return 0, ErrOverflow
		}
		v = v*10 + d
		p.pos++
	}
	return v, nil
}

func add(a, b int64) (int64, error) {
	s := a + b
	if (a >= 0) == (b >= 0) && (s >= 0) != (a >= 0) {
		return 0, ErrOverflow
	}
	return s, nil
}

func sub(a, b int64) (int64, error) {
	d := a - b
	if (a >= 0) != (b >= 0) && (d >= 0) != (a >= 0) {
		return 0, ErrOverflow
	}
	return d, nil
}

func mul(a, b int64) (int64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	p := a * b
	if (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) || p/b != a {
		return 0, ErrOverflow
	}
	return p, nil
}

func div(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	if a == math.MinInt64 && b == -1 {
		return 0, ErrOverflow
	}
	return a / b, nil
}

func rem(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	if b == -1 {
		// Avoids the MinInt64 % -1 edge case; the remainder is always 0.
		return 0, nil
	}
	return a % b, nil
}

package calc

import (
	"errors"
	"strings"
	"testing"
)

func TestEvaluate(t *testing.T) {
	tests := []struct {
		in   string
		want int64
		err  error
	}{
		{"1 + 2 * 3", 7, nil},
		{"-7 / 2", -3, nil},
		{"-7 % 3", -1, nil},
		{"7 % -3", 1, nil},
		{"--5", 5, nil},
		{"\t( 1+2 )\t* 3 ", 9, nil},
		{"10 - 4 - 3", 3, nil},
		{"9223372036854775807", 9223372036854775807, nil},
		{"-9223372036854775807 - 1", -9223372036854775808, nil},
		{"(-9223372036854775807 - 1) % -1", 0, nil},
		{"(-9223372036854775807 - 1) / -1", 0, ErrOverflow},
		{"-(-9223372036854775807 - 1)", 0, ErrOverflow},
		{"-9223372036854775808", 0, ErrOverflow},
		{"9223372036854775807 + 1", 0, ErrOverflow},
		{"3037000500 * 3037000500", 0, ErrOverflow},
		{"(-9223372036854775807 - 1) * -1", 0, ErrOverflow},
		{"1 / 0", 0, ErrDivByZero},
		{"1 % 0", 0, ErrDivByZero},
		{"(1 + 2", 0, ErrSyntax},
		{"1 2", 0, ErrSyntax},
		{"+1", 0, ErrSyntax},
		{"()", 0, ErrSyntax},
		{"1\r", 0, ErrSyntax},
		{"1 +", 0, ErrSyntax},
	}
	for _, tt := range tests {
		got, err := Evaluate([]byte(tt.in))
		if !errors.Is(err, tt.err) || (err == nil && got != tt.want) {
			t.Errorf("Evaluate(%q) = %d, %v; want %d, %v", tt.in, got, err, tt.want, tt.err)
		}
	}
}

func TestDeepNesting(t *testing.T) {
	const depth = 1_000_000
	expr := strings.Repeat("(", depth) + "42" + strings.Repeat(")", depth)
	if got, err := Evaluate([]byte(expr)); err != nil || got != 42 {
		t.Fatalf("got %d, %v; want 42", got, err)
	}
}

// Command app evaluates one integer expression per line of standard input
// and prints its value, or "error".
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"calc/calc"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "calc:", err)
	}
}

func run(r io.Reader, w io.Writer) error {
	in := bufio.NewReaderSize(r, 1<<16)
	out := bufio.NewWriterSize(w, 1<<16)
	var buf []byte
	for {
		line, err := in.ReadSlice('\n')
		if errors.Is(err, bufio.ErrBufferFull) {
			buf = append(buf, line...)
			continue
		}
		if len(buf) > 0 {
			buf = append(buf, line...)
			line = buf
		}
		line = bytes.TrimSuffix(line, []byte{'\n'})
		emit(out, line)
		buf = buf[:0]
		if err == io.EOF {
			break
		}
		if err != nil {
			out.Flush()
			return err
		}
	}
	return out.Flush()
}

func emit(out *bufio.Writer, line []byte) {
	if calc.IsBlank(line) {
		return
	}
	v, err := calc.Evaluate(line)
	if err != nil {
		out.WriteString("error\n")
		return
	}
	var num [20]byte
	out.Write(strconv.AppendInt(num[:0], v, 10))
	out.WriteByte('\n')
}
